//반송처리
scwin.vScrenID = "ULDINS90300.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : ins_register
 * 설명       : 반송처리 한다.
 ***********************************************/
scwin.ins_register = function() {
    //trs_modify.Action="/CmmInfoAction.do?method=processReturnInfo&inputMessageId=ULDINS90300_INPUT&SCREN_ID=" + vScrenID +"&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03 ;


    //alert(dts_UserList.text);

    //dts_return.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_return.insertRow();
    dts_return.setCellData(1, "KEY_ID", $c.stf.getObjectValue(txb_KEY));
    dts_return.setCellData(1, "RET_RSN", $c.stf.getObjectValue(txb_RET_RSN));
    dts_return.setCellData(1, "RET_RSN_FLAG", $c.stf.getObjectValue(txb_RET_RSN_FLAG));
    dts_return.setCellData(1, "RET_REQ_ID", $c.stf.getObjectValue(txb_REQ_ID));
    trs_modify.Action = "/CmmInfoAction.do?method=processReturnInfo" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    trs_modify.KeyName = "toinb_dataid4";
    trs_modify.KeyValue = "JSP(O:pReturnOut=dts_Rst,I:pInput=dts_return)";
    trs_modify.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
    trs_modify.Post();
};


/********************************************** 
 * 함수명   : ins_detail
 * 설명       : 신청인 이름, 휴대전화번호, 이메일을 조회한다.
 ***********************************************/
scwin.ins_detail = function(KEY_ID) {
    //데이터셋 초기화
    dts_detail.removeAll();
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS90300_VIEW_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&{P}KEY_ID=" + $c.stf.getObjectValue(txb_KEY);

    //alert(getObjectValue(txb_RET_RSN_FLAG));

    // 신청인 정보조회
    if ($c.stf.getObjectValue(txb_RET_RSN_FLAG) == "3") {
        // 표준코드 신청  반송 ret_rsn_flag = 3 
        url += "&queryId=lds.ins.common.select.listReturnInfo3";
    } else {
        // 발행기관 신청, 변경  반송 ret_rsn_flag = 1 , 2
        url += "&queryId=lds.ins.common.select.listReturnInfo12";
    }
    dts_detail.DataID = encodeURI(url);
    dts_detail.reset();
};



/********************************************** 
 * 함수명   : readTempCode
 * 설명       : 발행기관신청 반송처리일때 임시코드로 발행한 표준코드가 있는지 확인
 ***********************************************/
scwin.readTempCode = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS90300_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.common.select.listReturnInfo21" + "&{P}KEY_ID=" + $c.stf.getObjectValue(txb_KEY);

    // alert(url);
    dts_TempRst.DataID = encodeURI(url);
    dts_TempRst.reset();
};
scwin.btn_confirm_onclick = function() {
    /*
    if(txb_ENCRYP_APCT_EMAIL.value =="" || txb_ENCRYP_APCT_EMAIL.value.indexOf(" ") == "" ) {
    	alert( getMessageParam("MSG-A005", "이메일") );
    	txb_RET_RSN.focus();
    	return;
    }

    if(txb_APCT_CELLPHONE_NO.value =="" || txb_APCT_CELLPHONE_NO.value.indexOf(" ") == "" ) {
    	alert( getMessageParam("MSG-A005", "휴대번호") );
    	txb_RET_RSN.focus();
    	return;
    }
    */
    if (txb_RET_RSN.getValue() == "" || txb_RET_RSN.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "사유"));
        txb_RET_RSN.focus();
        return;
    }
    if (!$c.stf.checkMaxLength(txb_RET_RSN, 80, "사유")) {
        //txb_RET_RSN.value = "";
        txb_RET_RSN.focus();
        return false;
    }
    var rtn = confirm('반송 하시겠습니까?');
    if (rtn == 1) // [반송] 버튼이 눌려졌을 경우

    {
        scwin.ins_register();
    }
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_2);
    var arrPar = new Array();
    var parentWin = $c.frame.path("../");
    var fn_GetPar = parentWin.fn_GetParam;
    $c.stf.showObj(txb_mail_info, false);
    if (fn_GetPar != undefined) {
        fn_GetPar(arrPar);
        // 발행기관일경우 발행기관신청ID(ISUR_APPL_ID) , 표준코드 표준코드신청ID(STD_CD_APPL_ID)
        txb_KEY.setValue(((arrPar.length >= 1) && (arrPar[0] != undefined) ? arrPar[0] : ""));
        // 발행기관 신청에서  반송 ret_rsn_flag = 1 
        // 발행기관 변경신청 반송 ret_rsn_flag = 2
        // 표준코드 신청  반송 ret_rsn_flag = 3 
        txb_RET_RSN_FLAG.setValue(((arrPar.length >= 1) && (arrPar[1] != undefined) ? arrPar[1] : ""));
        txb_RET_RSN.focus();
        txb_flag.setValue("한글종목명");
        txb_code.setValue("접수번호");
        var sd = $c.frame.path("../").scwin.vScrenID;
        if (sd == "ULDINS05500.gfm") //발행기관신규접수

        {
            txb_ISU_NM.setValue($c.stf.getObjectValue($c.frame.path("../").txb_COM_NM));
            txb_APCT_NM.setValue($c.stf.getObjectValue($c.frame.path("../").txb_CHRG_NM));
            txb_APCT_CELLPHONE_NO.setValue($c.stf.getObjectValue($c.frame.path("../").txb_APCT_CELLPHONE_NO));
            txb_ENCRYP_APCT_EMAIL.setValue($c.stf.getObjectValue($c.frame.path("../").txb_ENCRYP_CHRG_EMAIL));
            txb_REQ_ID.setValue($c.stf.getObjectValue($c.frame.path("../").txb_REQ_ID));
            txb_flag.setValue("발행기관명");
        } else if (sd == "ULDINS05600.gfm") //발행기관 변경접수

        {
            txb_ISU_NM.setValue($c.stf.getObjectValue($c.frame.path("../").txb_ISUR_NM));
            txb_APCT_NM.setValue($c.stf.getObjectValue($c.frame.path("../").txb_CHRG_NM));
            txb_APCT_CELLPHONE_NO.setValue($c.stf.getObjectValue($c.frame.path("../").txb_ENCRYP_CELLPHONE_NO));
            txb_ENCRYP_APCT_EMAIL.setValue($c.stf.getObjectValue($c.frame.path("../").txb_ENCRYP_CHRG_EMAIL));
            txb_REQ_ID.setValue($c.stf.getObjectValue($c.frame.path("../").txb_REQ_ID));
            txb_flag.setValue("발행기관명");
        } else if (sd == "ULDINS10000.gfm" || sd == "ULDINS11200.gfm") //주권접수, 투자계약증권

        {
            txb_ISU_NM.setValue($c.stf.getObjectValue($c.frame.path("../").txb_ISU_KOR_NM));
            txb_APCT_NM.setValue($c.stf.getObjectValue($c.frame.path("../").txb_APCT_NM));
            txb_APCT_CELLPHONE_NO.setValue($c.stf.getObjectValue($c.frame.path("../").txb_APCT_CELLPHONE_NO));
            txb_ENCRYP_APCT_EMAIL.setValue($c.stf.getObjectValue($c.frame.path("../").txb_ENCRYP_APCT_EMAIL));
        } else if (sd == "ULDINS10100.gfm" || sd == "ULDINS10900.gfm") //채권접수, 전자단기사채/CP접수

        {
            txb_ISU_NM.setValue($c.stf.getObjectValue($c.frame.path("../").txb_REQ_ISU_NM));
            txb_APCT_NM.setValue($c.stf.getObjectValue($c.frame.path("../").txb_APCT_NM));
            txb_APCT_CELLPHONE_NO.setValue($c.stf.getObjectValue($c.frame.path("../").txb_APCT_CELLPHONE_NO));
            txb_ENCRYP_APCT_EMAIL.setValue($c.stf.getObjectValue($c.frame.path("../").txb_ENCRYP_APCT_EMAIL));
            if (sd == "ULDINS10100.gfm") {
                //채권접수
                var stdCdReqEmpNm = $c.stf.getObjectValue($c.frame.path("../").txb_STD_CD_REQ_EMP_NM);
                if (stdCdReqEmpNm != '') {
                    txb_APCT_CELLPHONE_NO.setValue('');
                    txb_ENCRYP_APCT_EMAIL.setValue('');
                    $c.stf.showObj(txb_mail_info, true);
                }
            }
        } else if (sd == "ULDINS10300.gfm" || sd == "ULDINS10400.gfm" || sd == "ULDINS10500.gfm" || sd == "ULDINS10600.gfm" || sd == "ULDINS11100.gfm") {
            //주식워런트(ELW)접수, 수익증권접수, 예탁증서(DR)접수, 신주인수권증권/증서접수, 상장지수증권(ETN)접수
            txb_ISU_NM.setValue($c.stf.getObjectValue($c.frame.path("../").txb_ISU_NM));
            txb_APCT_NM.setValue($c.stf.getObjectValue($c.frame.path("../").txb_APCT_NM));
            txb_APCT_CELLPHONE_NO.setValue($c.stf.getObjectValue($c.frame.path("../").txb_APCT_CELLPHONE_NO));
            txb_ENCRYP_APCT_EMAIL.setValue($c.stf.getObjectValue($c.frame.path("../").txb_ENCRYP_APCT_EMAIL));
        } else if (sd == "ULDINS10700.gfm") //스트립접수

        {
            txb_ISU_NM.setValue($c.stf.getObjectValue($c.frame.path("../").txb_OBJ_ISU_NM));
            txb_APCT_NM.setValue($c.stf.getObjectValue($c.frame.path("../").txb_APCT_NM));
            txb_APCT_CELLPHONE_NO.setValue($c.stf.getObjectValue($c.frame.path("../").txb_APCT_CELLPHONE_NO));
            txb_ENCRYP_APCT_EMAIL.setValue($c.stf.getObjectValue($c.frame.path("../").txb_ENCRYP_APCT_EMAIL));
        } else if (sd == "ULDINS10800.gfm") //양도성예금증서(CD) 표준코드접수

        {
            txb_ISU_NM.setValue($c.stf.getObjectValue($c.frame.path("../").txb_APPL_ISU_NM));
            txb_APCT_NM.setValue($c.stf.getObjectValue($c.frame.path("../").txb_APCT_NM));
            txb_APCT_CELLPHONE_NO.setValue($c.stf.getObjectValue($c.frame.path("../").txb_APCT_CELLPHONE_NO));
            txb_ENCRYP_APCT_EMAIL.setValue($c.stf.getObjectValue($c.frame.path("../").txb_ENCRYP_APCT_EMAIL));
        } else if (sd == "ULDINS10200.gfm") //ELS/DLS 접수

        {
            txb_ISU_NM.setValue($c.stf.getObjectValue($c.frame.path("../").txb_ISU_NM) + " " + $c.stf.getObjectValue($c.frame.path("../").txb_UNQ_ISU_NM));
            txb_APCT_NM.setValue($c.stf.getObjectValue($c.frame.path("../").txb_APCT_NM));
            txb_APCT_CELLPHONE_NO.setValue($c.stf.getObjectValue($c.frame.path("../").txb_APCT_CELLPHONE_NO));
            txb_ENCRYP_APCT_EMAIL.setValue($c.stf.getObjectValue($c.frame.path("../").txb_ENCRYP_APCT_EMAIL));
        }
        txb_KEYVALUE.setValue(txb_KEY.getValue());

        //alert(arrPar[0] + " " + arrPar[1]);

        //showObj(txb_KEY,false);
        //showObj(txb_RET_RSN_FLAG,false);

        //setObjectValue(rdo_PARAM,"중복신청");
        //setObjectValue(txb_RET_RSN,"중복신청");

    }

    //발행기관신청 반송처리일때 임시코드로 발행한 표준코드가 있는지 확인
    if ($c.stf.getObjectValue(txb_RET_RSN_FLAG) == "1") {
        //발행기관신청 반송시
        scwin.readTempCode();
    }
    //2016.09.21 신청인 이름, 휴대전화번호, 이메일을 조회한다. (전화면에서 가져오는 방법으로 변경)

    //alert(txb_KEY.value);

    //ins_detail(txb_KEY.value);

};
scwin.trs_modify_OnSuccess = function() {
    // 메시지는 pReturnOut 을이용 dts_Rst - OnLoadCompleted 에서 한다. 

};
scwin.trs_modify_OnFail = function() {
    alert_tr_error(trs_modify);
};
scwin.btn_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_Rst_OnLoadCompleted = async function(rowcount) {
    var RESULT_CONTN = dts_Rst.getCellData(0, "RESULT_CONTN");
    if (RESULT_CONTN == "ERROR1") {
        $c.win.alert("표준코드 신청자가 없습니다.확인부탁드립니다.");
    } else if (RESULT_CONTN == "ERROR2") {
        $c.win.alert("발행기관 신청자가 없습니다.확인부탁드립니다.");
    } else if (RESULT_CONTN == "SUCCESS") {
        $c.win.alert("정상적으로 반송처리 되었습니다.");
        $c.frame.path("../").ins_return();
        await $c.frame.CloseFrame();
    }
};
scwin.txb_RET_RSN_onkeyup = function() {
    fn_DelChar5(this);
};
scwin.rdo_PARAM_OnClick = function() {
    txb_RET_RSN.setValue($c.stf.getObjectValue(rdo_PARAM));
};
scwin.dts_TempRst_OnLoadCompleted = function(rowcount) {
    if (rowcount > 0) {
        var tempMsg = "현재 임시 발행기관코드로 발행한 표준코드가 같이 반송됩니다.\n";
        for (var i = 1; i <= rowcount; i++) {
            var std_cd_appl_id = dts_TempRst.getCellData(i, "STD_CD_APPL_ID");
            var std_cd_appl_contn_tp_nm = dts_TempRst.getCellData(i, "STD_CD_APPL_CONTN_TP_NM");
            var isu_nm = dts_TempRst.getCellData(i, "ISU_NM");
            tempMsg += std_cd_appl_contn_tp_nm + "(" + std_cd_appl_id + ") " + isu_nm + "\n";
        }
        $c.win.alert(tempMsg);
    }
};
